from flask import Flask, jsonify, request
import yaml

app = Flask(__name__)

class Template:
    def __init__(self, template_string):
        self.template = template_string
        self.variables = []

        for line in template_string.split('\n'):
            for word in line.split():
                if (word.startswith('{') and word.endswith('}')):
                    self.variables.append(word[1:-1])

    def render(self, data):
        result = self.template

        for variable in self.variables:
            if variable in data:
                result = result.replace('{'+variable+'}', str(data[variable]))
            else:
                result = result.replace('{'+variable+'}', '')

        return result

templates = {}

@app.route("/template", methods=['POST'])
def add_template():
    data = request.get_json()
    template_id = len(templates) + 1
    templates[template_id] = Template(data['template'])
    return {'id': template_id}

@app.route("/render/<int:template_id>", methods=['POST'])
def render(template_id):
    yaml_data = request.data
    data = yaml.load(yaml_data)
    template = templates[template_id]
    rendered = template.render(data)
    return rendered

if __name__ == "__main__":
    app.run()
